ELECT 1468058700, 1468059300, '2016:1468058700:1468059300', 600, 'lt_1h' UNION ALL SELECT 1468202700, 1468203300, '2016:1468202700:1468203300', 600, 'lt_1h' UNION ALL SELECT 1468297200, 1468305000, '2016:1468297200:1468305000', 7800, '1h_to_lt_1d' UNION ALL SELECT 1468305000, 1468305900, '2016:1468305000:1468305900', 900, 'lt_1h' UNION ALL SELECT 1468307100, 1468315200, '2016:1468307100:1468315200', 8100, '1h_to_lt_1d' UNION ALL SELECT 1468315500, 1468316100, '2016:1468315500:1468316100', 600, 'lt_1h' UNION ALL SELECT 1468317900, 1468318500, '2016:1468317900:1468318500', 600, 'lt_1h' UNION ALL SELECT 1468324500, 1468325100, '2016:1468324500:1468325100', 600, 'lt_1h' UNION ALL SELECT 1468329000, 1468329600, '2016:1468329000:1468329600', 600, 'lt_1h' UNION ALL SELECT 1468333800, 1468334400, '2016:1468333800:1468334400', 600, 'lt_1h' UNION ALL SELECT 1468337400, 1468338300, '2016:1468337400:1468338300', 900, 'lt_1h' UNION ALL SELECT 1468338600, 1468339200, '2016:1468338600:1468339200', 600, 'lt_1h' UNION ALL SELECT 1468340100, 1468340700, '2016:1468340100:1468340700', 600, 'lt_1h' UNION ALL SELECT 1468341300, 1468341900, '2016:1468341300:1468341900', 600, 'lt_1h' UNION ALL SELECT 1468342500, 1468343100, '2016:1468342500:1468343100', 600, 'lt_1h' UNION ALL SELECT 1468343700, 1468344300, '2016:1468343700:1468344300', 600, 'lt_1h' UNION ALL SELECT 1468344900, 1468345500, '2016:1468344900:1468345500', 600, 'lt_1h' UNION ALL SELECT 1468346100, 1468395300, '2016:1468346100:1468395300', 49200, '1h_to_lt_1d' UNION ALL SELECT 1468395300, 1468395900, '2016:1468395300:1468395900', 600, 'lt_1h' UNION ALL SELECT 1468396500, 1468397100, '2016:1468396500:1468397100', 600, 'lt_1h' UNION ALL SELECT 1468397700, 1468398300, '2016:1468397700:1468398300', 600, 'lt_1h' UNION ALL SELECT 1468398900, 1468399500, '2016:1468398900:1468399500', 600, 'lt_1h' UNION ALL SELECT 1468400100, 1468400700, '2016:1468400100:1468400700', 600, 'lt_1h' UNION ALL SELECT 1468401300, 1468401900, '2016:1468401300:1468401900', 600, 'lt_1h' UNION ALL SELECT 1468402500, 1468403100, '2016:1468402500:1468403100', 600, 'lt_1h' UNION ALL SELECT 1468403700, 1468404300, '2016:1468403700:1468404300', 600, 'lt_1h' UNION ALL SELECT 1468404900, 1468405500, '2016:1468404900:1468405500', 600, 'lt_1h' UNION ALL SELECT 1468406100, 1468406700, '2016:1468406100:1468406700', 600, 'lt_1h' UNION ALL SELECT 1468407300, 1468407900, '2016:1468407300:1468407900', 600, 'lt_1h' UNION ALL SELECT 1468408500, 1468409100, '2016:1468408500:1468409100', 600, 'lt_1h' UNION ALL SELECT 1468409700, 1468410300, '2016:1468409700:1468410300', 600, 'lt_1h' UNION ALL SELECT 1468410900, 1468411500, '2016:1468410900:1468411500', 600, 'lt_1h' UNION ALL SELECT 1468412100, 1468412700, '2016:1468412100:1468412700', 600, 'lt_1h' UNION ALL SELECT 1468413300, 1468413900, '2016:1468413300:1468413900', 600, 'lt_1h' UNION ALL SELECT 1468414500, 1468415100, '2016:1468414500:1468415100', 600, 'lt_1h' UNION ALL SELECT 1468415700, 1468416300, '2016:1468415700:1468416300', 600, 'lt_1h' UNION ALL SELECT 1468416900, 1468417500, '2016:1468416900:1468417500', 600, 'lt_1h' UNION ALL SELECT 1468418100, 1468418700, '2016:1468418100:1468418700', 600, 'lt_1h'), wh_hits AS (
 SELECT t.gap_id,t.gap_band,t.left_time,t.right_time,a.dateTime ts,
        a.usUnits wh_units,a.`interval` wh_interval,a.outTemp wh_temp,a.outHumidity wh_rh,
        a.rain wh_rain,a.rainRate wh_rainRate,a.windSpeed wh_wind
 FROM targets t JOIN weewx_WH1080.archive a
   ON a.dateTime>t.left_time AND a.dateTime<t.right_time AND MOD(a.dateTime-t.left_time,300)=0
 LEFT JOIN loucka_reconstruction.archive r ON r.dateTime=a.dateTime
 WHERE r.dateTime IS NULL
)
SELECT CAST(SUBSTRING_INDEX(h.gap_id,':',1) AS UNSIGNED) utc_year,h.gap_band,
 CASE WHEN h.ts>=1514764800 AND h.ts<1522540800 THEN 'PROTECTED_Q1_2018_DIAGNOSTIC' ELSE 'NORMAL' END protection_scope,
 COUNT(*) wh1080_rows,SUM(o.dateTime IS NOT NULL) old_weewx_rows,
 SUM(o.dateTime IS NULL) old_weewx_missing,
 SUM(h.wh_units=17) wh_units17,SUM(h.wh_interval=5) wh_interval5,
 SUM(o.usUnits<=>h.wh_units) units_equal,SUM(o.`interval`<=>h.wh_interval) intervals_equal,
 SUM(o.outTemp<=>h.wh_temp) outTemp_equal,SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL) outTemp_both_present,
 SUM(o.outTemp IS NOT NULL AND h.wh_temp IS NOT NULL AND o.outTemp<>h.wh_temp) outTemp_conflict,
 SUM(h.wh_temp=0) wh_outTemp_zero,SUM(h.wh_temp IS NULL) wh_outTemp_null,
 SUM(o.outHumidity<=>h.wh_rh) outHumidity_equal,SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL) outHumidity_both_present,
 SUM(o.outHumidity IS NOT NULL AND h.wh_rh IS NOT NULL AND o.outHumidity<>h.wh_rh) outHumidity_conflict,
 SUM(h.wh_rh IS NULL) wh_outHumidity_null,
 SUM(o.rain<=>h.wh_rain) rain_equal,SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL) rain_both_present,
 SUM(o.rain IS NOT NULL AND h.wh_rain IS NOT NULL AND o.rain<>h.wh_rain) rain_conflict,
 SUM(h.wh_rain IS NULL) wh_rain_null,
 SUM(o.rainRate<=>h.wh_rainRate) rainRate_equal,SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL) rainRate_both_present,
 SUM(o.rainRate IS NOT NULL AND h.wh_rainRate IS NOT NULL AND o.rainRate<>h.wh_rainRate) rainRate_conflict,
 SUM(h.wh_rainRate IS NULL) wh_rainRate_null,
 SUM(o.windSpeed<=>h.wh_wind) windSpeed_equal,SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL) windSpeed_both_present,
 SUM(o.windSpeed IS NOT NULL AND h.wh_wind IS NOT NULL AND o.windSpeed<>h.wh_wind) windSpeed_conflict,
 SUM(h.wh_wind IS NULL) wh_windSpeed_null
FROM wh_hits h LEFT JOIN old_weewx.archive o ON o.dateTime=h.ts
GROUP BY utc_year,h.gap_band,protection_scope
